/* Native engine tests: ALSA writes captured; no device opened or MIDI sent. */
#include <assert.h>
#define snd_seq_event_output_direct test_output
#define snd_seq_remove_events test_remove
#include "../src/engine.c"
#undef snd_seq_event_output_direct
#undef snd_seq_remove_events
static snd_seq_event_t sent[16384];static int ns,removed;
int test_output(snd_seq_t *s,snd_seq_event_t *v){(void)s;assert(ns<16384);sent[ns++]=*v;return 0;}
int test_remove(snd_seq_t *s,snd_seq_remove_events_t *r){(void)s;unsigned condition=snd_seq_remove_events_get_condition(r);assert(condition&SND_SEQ_REMOVE_TAG_MATCH);if(condition&SND_SEQ_REMOVE_TIME_AFTER){const snd_seq_timestamp_t *t=snd_seq_remove_events_get_time(r);assert(t->time.tv_sec>0);assert(snd_seq_remove_events_get_queue(r)==1);}removed++;return 0;}
static Engine *fresh(void){Engine *e=calloc(1,sizeof *e);assert(e);e->sample_rate=48000;e->mode=1;e->state_valid=1;e->random=123;for(int i=0;i<LANES;i++){init_lane(&e->lane[i],i);e->active_note[i]=-1;e->reset_at[i]=-1;}mod_init(e);e->seq=(snd_seq_t*)1;e->port=1;e->queue=1;snd_seq_remove_events_malloc(&e->rem);return e;}
static void done(Engine *e){snd_seq_remove_events_free(e->rem);free(e);}
static void put(Engine *e,const char *k,int v){char s[32];snprintf(s,sizeof s,"%d",v);set_param(e,k,s);}
static void defaults_and_state(void){Engine *e=fresh(),*t=fresh();for(int i=0;i<MOD_SLOTS;i++){assert(e->mod_pad[i]==-1);for(int j=0;j<2;j++)assert(!e->mod[i].osc[j].f[0]&&!e->mod[i].osc[j].f[8]);}put(e,"mod_choose3",1);put(e,"mod_pad",16);put(e,"mod1_on",1);put(e,"mod1_dest",7);put(e,"mod1_c7",-88);put(e,"mod_mix",-60);char s[32768];int len=write_evolution(e,s,sizeof s);assert(len>0&&len<32768&&!strncmp(s,"PICN6 ",6));assert(read_evolution(t,s));assert(!memcmp(t->mod,e->mod,sizeof e->mod));assert(!memcmp(t->mod_pad,e->mod_pad,sizeof e->mod_pad));assert(t->mod_selected==3);assert(!memcmp(t->lane,e->lane,sizeof e->lane));char old[32768];strcpy(old,s);old[4]='4';char *ext=strstr(old,"SCALE ");if(ext)strcpy(ext,"END");char *q=strstr(old,"END");assert(q);for(int i=0;i<1+MOD_SLOTS*(MOD_PER_LANE+1);i++){q--;while(q>old&&q[-1]!=' ')q--;}strcpy(q,"END");assert(read_evolution(t,old));for(int i=0;i<MOD_SLOTS;i++)assert(t->mod_pad[i]==-1&&!t->mod[i].osc[0].f[0]);ModLane before[MOD_SLOTS];memcpy(before,t->mod,sizeof before);s[len-1]='X';assert(!read_evolution(t,s));assert(!memcmp(before,t->mod,sizeof before));done(e);done(t);puts("PASS PICN6 state / PICN4 fallback / malformed atomic rejection");}
static void latch_and_ranges(void){Engine *e=fresh();int v[6];put(e,"mod_pad",1);mod_step_values(e,0,0,0,0,120,v);assert(v[0]==112&&v[1]==100&&v[3]==50&&v[4]==1);put(e,"mod0_on",1);put(e,"mod0_dest",5);put(e,"mod0_offset",100);mod_step_values(e,0,1,0,0,120,v);assert(v[4]==8);put(e,"mod0_offset",-100);mod_step_values(e,0,1,0,.1,120,v);assert(v[4]==8);mod_step_values(e,0,2,0,.1,120,v);assert(v[4]==1);put(e,"mod0_dest",1);put(e,"mod0_offset",-100);mod_step_values(e,0,3,0,0,120,v);assert(v[0]>=1);put(e,"mod0_depth",99999);assert(e->mod[0].osc[0].f[5]==100);assert(e->lane[0].f[4]==112);done(e);puts("PASS modulation bounds / immutable base / ratchet latching");}
static void priority(void){Engine *e=fresh();ns=removed=0;e->lane[1].f[9]=note(e,0);Hit pattern_hit={0,0,0,100,0,.1,0};trigger(e,&pattern_hit,120,1,INFINITY);assert(ns==2);Hit on={1,0,0,100,0,0,2};mod_trigger(e,&on,1.01);assert(removed==1&&e->mod_owner[1]==0&&e->active_note[0]<0);int n=ns;trigger(e,&pattern_hit,120,1.02,INFINITY);assert(ns==n);Hit second={0,0,1,100,0,0,2};mod_trigger(e,&second,1.03);assert(e->mod_owner[0]==1&&e->mod_owner[1]<0);Hit oldoff={1,0,0,0,0,0,1};n=ns;mod_trigger(e,&oldoff,1.04);assert(ns==n&&e->mod_owner[0]==1);Hit off={0,0,1,0,0,0,1};mod_trigger(e,&off,1.05);assert(e->active_note[0]<0&&!mod_pattern_blocked(e,0));trigger(e,&pattern_hit,120,1.06,INFINITY);assert(ns==n+3);release(e,0);assert(e->active_note[0]<0);done(e);puts("PASS same-address takeover / stale off / pattern suppression / resumption / release");}
static void crossings(void){Engine *e=fresh();put(e,"mod_pad",1);put(e,"mod0_on",1);put(e,"mod0_dest",7);put(e,"mod0_wave",4);put(e,"mod0_depth",100);put(e,"mod_mix",-100);mod_advance(e,0,120);Hit h[EVENTS];int n=0,budget=EVENTS;assert(mod_events(e,h,&n,0,.02,120,0,&budget));assert(n==0);/* enabled above threshold: no immediate note */mod_advance(e,12000,120);n=0;assert(mod_events(e,h,&n,1,1.02,120,0,&budget));assert(n==1&&h[0].kind==1);mod_advance(e,12000,120);n=0;assert(mod_events(e,h,&n,2,2.02,120,0,&budget));assert(n==1&&h[0].kind==2);double phase=e->mod_phase[0][0];put(e,"mod0_on",0);mod_advance(e,2400,120);assert(e->mod_phase[0][0]==phase);put(e,"mod0_on",1);e->lane[0].f[12]=1;mod_advance(e,2400,120);assert(e->mod_phase[0][0]==phase);e->lane[0].f[12]=0;mod_advance(e,2400,120);assert(e->mod_phase[0][0]>phase);done(e);puts("PASS edge arming / rising-falling / OFF/mute phase suspension and resume");}
static void baseline(void){Engine *e=fresh();ns=0;for(int i=1;i<16;i++)e->lane[i].f[12]=1;int b=EVENTS;assert(span(e,0,4,120,1,INFINITY,&b));assert(ns==8);for(int k=0;k<ns;k+=2){assert(sent[k].type==SND_SEQ_EVENT_NOTEON&&sent[k+1].type==SND_SEQ_EVENT_NOTEOFF);assert(sent[k].data.note.note==36);}done(e);puts("PASS modulation OFF: original four-hit lane output");}
static void contextual_controls(void){Engine *e=fresh();char b[32];put(e,"mod_choose2",1);put(e,"mod_pad",5);put(e,"mod0_depth",37);put(e,"mod1_dest",7);put(e,"mod_mix",-25);assert(e->mod[2].osc[0].f[5]==37&&e->mod[0].osc[0].f[5]==50);put(e,"line_select16",0);assert(get_param(e,"mod0_depth",b,sizeof b)>0&&!strcmp(b,"37"));put(e,"mod_choose0",1);assert(get_param(e,"mod0_depth",b,sizeof b)>0&&!strcmp(b,"50"));put(e,"mod_pad",5);assert(e->mod_pad[0]==-1);put(e,"mod_pad",13);put(e,"mod_choose2",1);assert(get_param(e,"mod0_depth",b,sizeof b)>0&&!strcmp(b,"37"));assert(e->mod_pad[0]==12&&e->mod_pad[2]==4);done(e);puts("PASS independent four-slot selection / lane selection / unique pad assignments");}
static void preview_and_reassign(void){Engine *e=fresh();put(e,"mod_pad",1);put(e,"mod0_on",1);put(e,"mod0_dest",7);int before[31];for(int k=0;k<31;k++)before[k]=mod_visual(e,LANES+5+k);assert(!(e->mod_trace_dirty&1));for(int i=0;i<100;i++)mod_advance(e,480,120);for(int k=0;k<31;k++)assert(before[k]==mod_visual(e,LANES+5+k));put(e,"mod0_offset",50);int changed=0;for(int k=0;k<31;k++)changed|=before[k]!=mod_visual(e,LANES+5+k);assert(changed);ns=0;Hit on={0,0,0,100,0,0,2};mod_trigger(e,&on,1);assert(e->mod_owner[0]==0);put(e,"mod_pad",13);assert(e->release_pending&1);release(e,0);assert(e->active_note[0]<0);assert(e->mod_pad[0]==12);done(e);puts("PASS static cached preview / edit refresh / reassignment note release");}
static void ui_targets_and_preview_window(void){Engine *e=fresh();put(e,"line_select16",3);put(e,"open_rhythm",1);assert(e->dialog==6);put(e,"mod_pad",13);assert(e->dialog==0&&e->mod_pad[0]==12&&e->selected==3);put(e,"open_rhythm",1);put(e,"apply_rhythm",1);assert(e->dialog==0&&e->mod_pad[0]==-1);put(e,"channel",15);assert(e->channel==0);put(e,"mod0_rate",4);mod_preview(e,0);int previous[31];memcpy(previous,e->mod_trace_cache[0][0],sizeof previous);put(e,"mod0_rate",5);mod_preview(e,0);assert(memcmp(previous,e->mod_trace_cache[0][0],sizeof previous));put(e,"mod0_sync",0);mod_preview(e,0);memcpy(previous,e->mod_trace_cache[0][0],sizeof previous);mod_advance(e,48,100);mod_preview(e,0);assert(memcmp(previous,e->mod_trace_cache[0][0],sizeof previous));put(e,"mod0_hz",1000);assert(mod_style(e,0)==2);done(e);puts("PASS pad layer closes / PATTERN selection retained / fixed channel / four-bar rate and Hz tempo previews");}
static void config_roundtrip(void){Engine *e=fresh(),*t=fresh();char state[32768];put(e,"l12_dnote",79);put(e,"l12_hold",1);put(e,"bank",7);put(e,"target_mode",0);put(e,"l12_pad",2);put(e,"l12_sound",3);assert(note(e,12)==79&&e->mode==1&&e->bank==0&&e->lane[12].f[10]==12);assert(write_evolution(e,state,sizeof state)>0&&read_evolution(t,state));assert(note(t,12)==79&&t->lane[12].hold==e->lane[12].hold);e->mode=0;e->bank=5;e->lane[12].f[8]=83;e->lane[12].f[9]=79;e->lane[12].f[10]=2;assert(write_evolution(e,state,sizeof state)>0&&read_evolution(t,state));assert(note(t,12)==83&&t->mode==1&&t->bank==0&&t->lane[12].f[10]==12);put(t,"l12_inote",81);assert(note(t,12)==81&&t->lane[12].f[8]==81);done(e);done(t);puts("PASS CONFIG: custom notes / hold / retired selectors / active legacy note preserved");}
static void selection_visual_scope(void){Engine *e=fresh();char key[64];visual_snapshot(e,0,1);while(mpc_engine_changed(e,key,sizeof key)>0){}assert(e->visual_ready);put(e,"line_select16",3);assert(e->visual_ready&&e->mod_selected==0);visual_snapshot(e,2048,0);int curve_notifications=0,n=0;while(mpc_engine_changed(e,key,sizeof key)>0){n++;if(key[0]=='g')curve_notifications++;}assert(!curve_notifications&&n<128);put(e,"mod_choose1",1);assert(e->visual_ready&&e->mod_selected==1);done(e);puts("PASS PATTERN selection: cached MOD visuals retained / contextual MOD selection retains global cache");}
static void stress(void){Engine *e=fresh();ns=removed=0;for(int i=0;i<MOD_SLOTS;i++){e->mod_pad[i]=i;for(int j=0;j<2;j++){e->mod[i].osc[j].f[0]=1;e->mod[i].osc[j].f[8]=7;e->mod[i].osc[j].f[2]=0;e->mod[i].osc[j].f[4]=1000;e->mod[i].osc[j].f[5]=100;}e->mod[i].osc[1].f[7]=90;mod_coefficients(e,i);}
 for(int block=0;block<2000;block++){mod_advance(e,48,120);int budget=EVENTS;assert(span(e,block*.002,(block+1)*.002,120,1+block*.001,INFINITY,&budget));}assert(!e->errors);assert(ns>500);panic_owned(e);for(int i=0;i<16;i++)assert(e->active_note[i]<0&&e->mod_owner[i]<0);
 for(int wave=0;wave<8;wave++){e->mod[0].osc[0].f[1]=wave;for(int n=0;n<1000;n++){double v=mod_wave_slot(e,0,0,n*.013);assert(isfinite(v)&&v>=-1.000001&&v<=1.000001);}}
 done(e);puts("PASS 8 LFOs at 20 Hz / shared budget / stop release / eight bounded waves");}
int main(void){defaults_and_state();latch_and_ranges();priority();crossings();baseline();contextual_controls();preview_and_reassign();ui_targets_and_preview_window();config_roundtrip();selection_visual_scope();stress();puts("ALL E01 TESTS PASSED");return 0;}
